\begin{ex}%[8H3V3]
\immini[thm]{
Cho hình bình hành ${EFKH}$ có $EF < KH$. Tia phân giác của góc $\widehat{F}$, $\widehat{H}$ lần lượt cắt ${EH, FK}$ tại ${I, J}$. Trong các khẳng định sau khẳng định nào sai?

\choice
{  $\Delta{KJH}$ cân tại ${K}$ }
   { Tứ giác ${FIHJ}$ là hình bình hành }
     { \True  Tứ giác ${FKHI}$ là hình thang cân  }
    {  $\Delta{EFI}$ cân tại ${E}$ }
}{
\begin{tikzpicture}
            \coordinate (M) at (-0.76, 0);
            \coordinate (D) at (2, 0);
            \coordinate (C) at (3, 2);
