            \draw[thick] (A) -- (B)--(C)--(D)--(A);
        \draw[thick] (N) -- (D) ;
            % Ghi nhãn các điểm
            \node[below right] at (M) {$I$};
            \node[above left] at (B) {$F$};
            \node[above right] at (C) {$K$};
