            \node[below left] at (A){$E$};
            \node[above right] at (N) {$J$};
                \draw 
            pic[draw,blue,angle radius=4mm] {angle = M--B--C}; 
             \draw  pic[draw,blue,angle radius=4.7mm] {angle = A--B--M};
